/**
 * // This is ArrayReader's API interface. // You should not implement it, or speculate about its
 * implementation interface ArrayReader { public int get(int index) {} }
 */
class Solution {
  public int search(ArrayReader reader, int target) {
    int left = 0, right = target - reader.get(0);

    while (left <= right) {
      int piv = (left + right) / 2, num = reader.get(piv);
      if (num == target) return piv;
      else if (num > target) right = piv - 1;
      else left = piv + 1;
    }
    return -1;
  }
}
